//We add theme as a argument in Storybook instead of having it nested in the product object.
type CustomArgs = ComponentProps<WithMockedDate<typeof UpsellItem>> & {
  theme: (typeof existingThemes)[number];
  /** Internal flag used to enable story-specific mocks */
  __mockMaximumQuantityReached?: boolean;
  products: StaticConfigContextType["products"];
};

const meta = {
  title: "Blocks/Group Admission/Upsell Item",
  component: UpsellItem,
  decorators: [withMockedDate],
  argTypes: {
    totalGroupSize: {
      table: {
        disable: true,
      },
    },
    selectedUpsellProduct: {
      table: {
        disable: true,
      },
    },
    selectedEntryTimeSlot: {
      table: {
        disable: true,
      },
    },
    selectedDate: {
      table: {
        disable: true,
      },
    },
    dispatch: {
      table: {
        disable: true,
      },
    },
    theme: {
      control: "select",
      options: existingThemes,
    },
    __mockMaximumQuantityReached: {
      table: { disable: true },
    },
  },

  render: function StoryComponent({ products, ...args }: CustomArgs) {
    // eslint-disable-next-line @tanstack/query/stable-query-client
    const queryClient = new QueryClient();

    products!.contentfulProducts ??= [];
    products!.glkProducts ??= [];
    products.contentfulProducts = products.contentfulProducts.map((product) => ({
      ...product,
      componentTheme: args.theme,
    }));

    const [selectedUpsellProduct, setSelectedUpsellProduct] = useState<SelectedUpsellProduct | undefined>(
      args.selectedUpsellProduct,
    );

    const dispatch = (value: any) => {
      switch (value.type) {
        default:
        case ActionType.UPDATE_UPSELL_PRODUCT:
          return setSelectedUpsellProduct(value.payload.upsellProduct as SelectedUpsellProduct);
        case ActionType.DELETE_UPSELL_PRODUCT:
          return setSelectedUpsellProduct(undefined);
      }
    };

    // Story-specific mocks to force maximumQuantityReached
    if (args.__mockMaximumQuantityReached) {
      const glkId = args.upsellProductId;
      const maximumQuantity = 4;

      products.glkProducts = products.glkProducts.map((product) => {
        if (product.id === glkId) {
          return {
            ...product,
            maximumQuantity,
          };
        }
        return product;
      });

      const cartId = "storybook-cart";
      localStorage.setItem("shop-service-cart-id", cartId);
      const cartMock = {
        cartGuid: cartId,
        state: CartState.OPEN,
        company: CompanyShortName.GLT,
        culture: "sv-SE",
        cartItems: [
          {
            cartItemGuid: "ci-1",
            productId: glkId,
            productName: "Mocked product in cart",
            price: {
              amount: {
                amountIncludingVat: 100,
                vatAmount: 20,
              },
              unitPriceIncludingVat: 100,
              vatPercentage: 25,
            },
            quantity: maximumQuantity,
            deliveryType: DeliveryType.DIGITAL,
          },
        ],
        cartPrice: {
          amount: {
            amountIncludingVat: 100.0,
            vatAmount: 20.0,
          },
        },
        timestamps: {
          createdOn: "2025-02-25T13:00:13.0597613",
          updatedOn: "2025-02-25T13:14:49.8990232",
          paymentInitializedOn: "2025-02-25T13:00:26.0350882",
          paymentCompletedOn: "2025-02-25T13:14:49.2644864",
          expiresOn: "2025-02-26T13:00:13.0597613",
        },
        voucherCodes: [],
        discountItems: [],
        redeemableValidationResults: [],
      } satisfies CartResponseV2;
      queryClient.setQueryData(["cart-items", cartId], cartMock);
    }

    return (
      <PageProviders
        currentContentPageData={{
          slugs: { sv: "", en: "" },
          currentLocale: "sv",
        }}
        staticConfigData={{
          eCommerce: {
            preferredPaymentProvider: "Klarna",
            shopServicePaymentSlug: "",
            shopServiceConfirmationSlug: "",
            shopServiceCheckoutSlug: "",
          },
          products,
        }}
        overrideQueryClient={queryClient}
      >
        <div
          //--common-wrapper to make it more like the group admission
          style={{
            maxWidth: "640px",
            color: "var(--common-wrapper-text-color)",
            background: "var(--common-wrapper-background)",
          }}
        >
          <UpsellItem {...args} selectedUpsellProduct={selectedUpsellProduct} dispatch={dispatch} />
        </div>
      </PageProviders>
    );
  },
} satisfies Meta<CustomArgs>;

export default meta;

